@startuml

class WebPortal {
  + versionNumber : string
  + url : string
}

class Building {
  + id : string
  + name : string
  + address : string
  + yearOfConstruction : int
}

enum EnergyClass {
  A
  B
  C
  D
}

class User {
  + userName : string
  + email : string
  + password : string
}

class Administrator {
  + idCardNumber : string
}

class Entry {
  + name : string
  + isPublic : boolean
}

class TextualEntry extends Entry {
  + text : string
}

class NumericalEntry extends Entry {
  + value : float
  + unit : string
}

class Image {
  + fileName : string
}

class Comment {
  + content : string
}

WebPortal "1" -- "*" Building
Building "1" -- "1" EnergyClass
Building "1" -- "1" User : owner
Building "1" *-- "*" Entry
Building "1" *-- "*" Image
Building "1" -- "0..1" Image : profile photo
User "1" -- "*" Building : creates
User "1" -- "*" Comment : writes
User "1" -- "*" Building : comments on
Administrator extends User
Administrator "1" -- "*" User : sets up
Administrator "1" -- "*" Comment : deletes

@enduml

